package bz.tikitmasta.customer;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
public class ApiClient{public interface Callback{void done(JSONObject r,String e);}static final String BASE="https://tikitmaster.com";public String absolute(String p){return p.startsWith("http")?p:BASE+p;}public void post(String path,JSONObject params,Callback cb){new Thread(()->{HttpURLConnection c=null;try{c=(HttpURLConnection)new URL(absolute(path)).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");JSONObject b=new JSONObject().put("jsonrpc","2.0").put("method","call").put("params",params).put("id",System.currentTimeMillis());try(OutputStream o=c.getOutputStream()){o.write(b.toString().getBytes(StandardCharsets.UTF_8));}InputStream in=c.getResponseCode()<400?c.getInputStream():c.getErrorStream();StringBuilder s=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8))){for(String l;(l=r.readLine())!=null;)s.append(l);}JSONObject env=new JSONObject(s.toString());cb.done(env.optJSONObject("result"),env.has("error")?env.optJSONObject("error").optString("message"):null);}catch(Exception e){cb.done(null,e.getMessage());}finally{if(c!=null)c.disconnect();}}).start();}}
